import { BaseButton, createStyles, Spacer, Text, useTheme } from '@core/ui';
import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { ScrollView } from 'react-native';

type PaginationPropsType = {
  totalPages: number;
  currentPage: number;
  setCurrentPage: (page: number) => void;
};
const Pagination: React.FC<PaginationPropsType> = (props) => {
  const { totalPages, currentPage, setCurrentPage } = props;
  const { theme } = useTheme();
  const styles = useStyles();
  const [currentPages, setCurrentPages] = useState(currentPage);

  useEffect(() => {
    if (currentPages !== currentPage) {
      setCurrentPages(currentPage);
    }
  }, [currentPage, currentPages]);

  const handlePress = (page: number) => {
    setCurrentPage(page);
    setCurrentPages(page);
  };
  const renderPaginationItem = (item, index: number) => {
    return (
      <BaseButton
        key={index.toString()}
        onPress={() => handlePress(index)}
        style={[
          styles.paginationItem,
          currentPages === index && styles.paginationItemActive,
        ]}
        disabled={currentPages === index}
      />
    );
  };
  console.log('renderPaginationItem', currentPage, currentPages);
  return (
    <ScrollView
      horizontal
      style={styles.flashListStyle}
      contentContainerStyle={styles.flashListContainerStyle}
      showsHorizontalScrollIndicator={false}
    >
      {Array(totalPages).fill(null).map(renderPaginationItem)}
    </ScrollView>
  );
};
const useStyles = createStyles((theme) => ({
  flashListStyle: {
    maxWidth: theme.Size.Horizontal.Gigantic,
    marginBottom: theme.Size.Vertical.Regular,
    alignSelf: 'center',
  },
  flashListContainerStyle: {
    justifyContent: 'center',
    alignItems: 'center',
    gap: theme.Size.Horizontal.Base,
  },
  paginationItem: {
    width: theme.Size.Horizontal.Base,
    height: theme.Size.Vertical.Base,
    backgroundColor: theme.Colors.Background.White + '99',
    borderRadius: theme.BorderRadius.md,
    justifyContent: 'center',
    alignItems: 'center',
  },
  paginationItemActive: {
    backgroundColor: theme.Colors.Main.Red,
    borderColor: theme.Colors.Base.White,
    borderWidth: 1,
  },
}));
export { Pagination };
