type VideoBackgroundPropsType = {
  pause: boolean;
  onVideoEnd: () => void;
  source: mediaType
  repeat?: boolean;
  muted?: boolean;
}
type mediaType = {
  id: number;
  name: string;
  media: string;
  destination: string;
}
const VideoBackground: React.FC<VideoBackgroundPropsType> = (props) => {
  const { theme } = useTheme();
  const { t, i18n } = useTranslation(['VideoBackground']);
  const { pause, onVideoEnd, source, repeat = false, muted = false } = props;
  const insets = useSafeAreaInsets();
  const [isMuteVideo, setIsMuteVideo] = useState(muted);
  const videoRef = useRef<VideoRef>(null);
  const styles = useStyles();
  console.log('VideoBackgroundMute', muted, isMuteVideo);
  useEffect(() => {
    if (isMuteVideo != muted) {
      setIsMuteVideo(muted);
    }
  }, [isMuteVideo, muted]);
  return (
    <View style={[styles.container]}>
      {/* <Image
        source={{ uri: 'https://media.gettyimages.com/id/515437010/photo/successful-young-entrepreneurs-analyzing-stock-market-data-in-office.jpg?s=2048x2048&w=gi&k=20&c=TXmKkLJv1QpJ4TS6FfTpqv5QQKlxbGXQ8xiE4qx4K6k=' }}
        style={styles.video}
      /> */}
      <Video
        // Can be a URL or a local file.
        source={{ uri: source?.media ? source?.media : 'https://loving-bear-8b04c0cb23.media.strapiapp.com/welcom_2_53cc31edc3.mp4' }}
        // Store reference
        ref={videoRef}
        onEnd={onVideoEnd}
        paused={pause}
        repeat={repeat}
        resizeMode="cover"
        ignoreSilentSwitch={'ignore'}
        removeClippedSubviews={true}
        muted={isMuteVideo}
        selectedAudioTrack={{ type: SelectedTrackType.SYSTEM }}
        style={styles.video}
      />

    </View>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    flex: 1,
    backgroundColor: 'transparent',
    // paddingHorizontal: theme.Size.Horizontal.Medium,
  },
  video: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
}));
export { VideoBackground };

