import React from 'react';
import {
  type NativeStackNavigationProp,
  createNativeStackNavigator,
} from '@react-navigation/native-stack';
import DrawerNavigator from './DrawerNavigator/DrawerNavigator';
import TabNavigation from './TabNavigation';
import { WebViewScreen } from '../webview/screens';

export type MainStackParamList = {
  Drawer: { selectedMenuTop: number };
  TabNavigation: { screen: string; params?: any };
  HomePage: { scrollVeticalIndex: number };
  WebViewScreen: { url: string; title: string };
};

export type MainStackNavigationProp =
  NativeStackNavigationProp<MainStackParamList>;

const Main = createNativeStackNavigator<MainStackParamList>();

const MainNavigator = () => {
  return (
    <Main.Navigator
      screenOptions={{
        headerShown: false,
      }}
    >
      <Main.Screen name="Drawer" component={DrawerNavigator} />
      <Main.Screen name="TabNavigation" component={TabNavigation} />
      <Main.Screen name="WebViewScreen" component={WebViewScreen} />
    </Main.Navigator>
  );
};

export default MainNavigator;
