import { createSlice } from '@reduxjs/toolkit';
import { Homepage } from '@src/domain/entities/homepage';
import { fetchHomepage } from './thunk';

interface HomepageState {
  data: Homepage | null;
  status: 'idle' | 'loading' | 'succeeded' | 'failed';
  error: string | null;
}

const initialState: HomepageState = {
  data: null,
  status: 'idle',
  error: null,
};

const homepageSlice = createSlice({
  name: 'homepage',
  initialState,
  reducers: {
    resetHomepage: (state) => {
      state.data = null;
      state.error = null;
      state.status = 'idle';
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchHomepage.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchHomepage.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.data = action.payload;
      })
      .addCase(fetchHomepage.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message ?? 'Failed to fetch homepage';
      });
  },
});

export default homepageSlice;
