import {
  StyleProp,
  StyleSheet,
  Text,
  TextStyle,
  TouchableOpacity,
} from 'react-native';
import React from 'react';
import { useTheme } from '@core/ui';

type BottomBarItemProps = {
  label?: string;
  icon: React.ReactNode;
  activeIcon?: React.ReactNode;
  isActive?: boolean;
  onPress: () => void;
  isFloating?: boolean;
};

const BottomBarItem = ({
  label,
  icon,
  activeIcon,
  isActive,
  onPress,
  isFloating,
}: BottomBarItemProps) => {
  const { theme } = useTheme();
  const { Fonts, Size, Colors } = theme;
  const TextCaption300 = {
    Bold: {
      fontFamily: Fonts.Bold,
      fontSize: Size.ms(10),
      lineHeight: Size.ms(12),
      color: Colors.Text.Black,
    },
  };
  const labelStyle: StyleProp<TextStyle> = {
    // ...theme.Typography.TextCaption300,
    ...TextCaption300.Bold,
  };

  return (
    <TouchableOpacity key={label} onPress={onPress} style={[styles.container, isFloating && { marginTop: -18 }]}>
      {isActive ? activeIcon : icon}
      {label ? <Text style={labelStyle}>{label}</Text> : null}
    </TouchableOpacity>
  );
};

export { BottomBarItem };

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    flex: 1,
  },
});
