import React from 'react';
import { createDrawerNavigator } from '@react-navigation/drawer';
import CustomDrawerContent from './CustomDrawerContent/CustomDrawerContent';
import { useTheme } from '@core/ui';
import TabNavigation from '../TabNavigation';
import { RouteProp, useRoute } from '@react-navigation/native';
import { MainStackParamList } from '../MainNavigator';
import { WebViewScreen } from '@src/presentation/webview/screens';
import { DrawerContentComponentProps } from '@react-navigation/drawer';

const Drawer = createDrawerNavigator();

const DrawerNavigator = ({}) => {
  const route = useRoute<RouteProp<MainStackParamList, 'Drawer'>>();
  const selectedMenuTop = route.params?.selectedMenuTop || 0;
  const { theme } = useTheme();

  const renderDrawerContent = (drawerProps: DrawerContentComponentProps) => (
    <CustomDrawerContent
      selectedMenuTop={selectedMenuTop}
      drawerProps={drawerProps}
    />
  );

  return (
    <Drawer.Navigator
      drawerContent={(props) => renderDrawerContent(props)}
      screenOptions={{
        headerShown: false,
        drawerStyle: { width: theme.Size.DEVICE_WIDTH / 1.3 },
      }}
    >
      <Drawer.Screen name="TabNavigation" component={TabNavigation} />
      <Drawer.Screen name="WebViewScreen" component={WebViewScreen} />
    </Drawer.Navigator>
  );
};
export default DrawerNavigator;
