import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback } from 'react';
import { useChangeLanguage, useTranslation } from '@core/service';
import { FlatList, Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { HomePageCardItem } from './HomePageCardItem';
import { HomePageCardItemSquares } from './HomePageCardItemSquares';
import { HomePageCardChartItem } from './HomePageCardChartItem';


type HomePageCardItemType = {
  order: number;
  id: number;
  title: string;
  description?: string;
  background_color: string;
  product_image: string;
  destination: string;
}
type HomePageCardType = {
  id: number;
  documentId: string;
  title: string;
  is_active: boolean;
  product_card_items: HomePageCardItemType[];
}
type HomePageCardPropsType = {
  data: HomePageCardType;
}


const HomePageCard: React.FC<HomePageCardPropsType> = (props) => {
  const { theme } = useTheme();
  const { data } = props;
  const { t, i18n } = useTranslation(['HomePageCard']);
  const styles = useStyles();
  const [isPersional, setIsPersional] = useState(true);
  const insets = useSafeAreaInsets();
  const renderItem = useCallback(({ item, index }: { item: HomePageCardItemType, index: number }) => {
    if (data?.id == 123 || data?.id == 125) {
      return (
        <HomePageCardItemSquares item={item} index={index} key={item?.id?.toString()} />
      );
    }
    else if (data?.id == 130) {
      return (
        <HomePageCardChartItem item={item} index={index} key={item?.id?.toString()} />
      );
    }
    return (
      <HomePageCardItem item={item} index={index} key={item?.id?.toString()} />
    );
  }, []);
  return (
    <View style={[styles.container]}>
      <FlatList showsHorizontalScrollIndicator={false} contentContainerStyle={styles.contentContainerStyle} style={styles.flatlist} horizontal data={data?.product_card_items} renderItem={renderItem} />
    </View>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    width: '100%',
  },
  contentContainerStyle: {
    gap: theme.Size.Horizontal.Medium,
    paddingHorizontal: theme.Size.Horizontal.xLarge,
  },
  flatlist: {
  },
}));
export { HomePageCard };
export type { HomePageCardType, HomePageCardItemType };
