import { BaseButton, createStyles, Text, useTheme } from '@core/ui';
import { BannerWelcome } from '@src/presentation/homepage/components';
import { HomePageMenu } from '@src/presentation/homepage/components/HomePageMenu';
import { Hotline } from '@src/presentation/homepage/components/Hotline';
import { LeftMenu } from '@src/presentation/homepage/components/LeftMenu';
import { Pagination } from '@src/presentation/homepage/components/Pagination/Pagination';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
// import { useTranslation } from '@core/service';
import { View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

type PageWelcomePropsType = {
  data: string[];
  isMuteVideo: boolean;
  setMuteVideo: () => void;
  indexHorizontal: number;
  setIndexHorizontal: (page: number) => void;
  totalPages: number;
};

const PageWelcome: React.FC<PageWelcomePropsType> = (props) => {
  const { theme } = useTheme();
  // const { t, i18n } = useTranslation(['PageWelcome']);
  const { data, setMuteVideo, isMuteVideo, indexHorizontal, totalPages, setIndexHorizontal } = props;

  const insets = useSafeAreaInsets();
  const styles = useStyles();
  const [currentPage, setCurrentPage] = useState(indexHorizontal);
  const [muted, setIsMuteVideo] = useState(isMuteVideo);
  useEffect(() => {
    if (currentPage !== indexHorizontal) {
      setCurrentPage(indexHorizontal);
    }
  }, [indexHorizontal]);
  const handlePagination = (page) => {
    setCurrentPage(page);
    setIndexHorizontal(page);
  };
  const handleMuteVideo = useCallback(() => {
    setMuteVideo(!muted);
    setIsMuteVideo(!muted);
  }, [muted]);
  console.log('pageWelcome', indexHorizontal, currentPage);
  return (
    <>
      <BannerWelcome data={data} />
      <View
        style={[styles.page, { bottom: theme.Size.ms(56) }]}
      >
        <LeftMenu
          setMuteVideo={handleMuteVideo}
          isMuteVideo={muted}
          data={data}
        />
        <Pagination
          currentPage={currentPage}
          setCurrentPage={handlePagination}
          totalPages={totalPages}
        />
        <HomePageMenu data={data} />
      </View>
    </>
  );
};
const useStyles = createStyles((theme) => ({
  page: {
    position: 'absolute',
    gap: theme.Size.Vertical.Medium,
    justifyContent: 'flex-end',
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'transparent',
  },
}));
export { PageWelcome };
