import {
  BaseButton,
  createStyles,
  Loader,
  LoadingBlockerView,
  Text,
  useTheme,
} from '@core/ui';
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
// import { useTranslation } from '@core/service';
import { Image, View } from 'react-native';
import { PageScroll } from './PageScroll';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { LogoFb, LogoTiktok, LogoYoutube, LogoZalo } from '@src/assets/images';
import { PageWelcome } from './PageWelcome';
import { PageSections } from './PageSections';
import { useSharedValue } from 'react-native-reanimated';
import Animated from 'react-native-reanimated';
import { STORAGE_KEY, Storage } from '@core/service';
import { isEmpty } from 'lodash';
import { HeaderBar, VideoBackground } from '../../components';
import { Hotline } from '../../components/Hotline';
import { ListSocial } from '../../components/ListSocial';
import { FlatList } from 'react-native-gesture-handler';
import {
  HomePageMenuData,
  HpProductSectionBackgroundData,
  HpProductSectionCard,
  HpProductSectionCardData,
  HpProductSectionData,
  HpWelcomeBackgroundData,
  HpWelcomeData,
} from '@src/domain/entities/homepage';
const homePageProductSection: HpProductSectionData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageProductSection.json');
const homePageProductSectionBackground: HpProductSectionBackgroundData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageProductSectionBackground.json');
const homePageProductSectionCard: HpProductSectionCardData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageProductSectionCard.json');
const homePageMenu: HomePageMenuData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepagemenu.json');
const homePageWelcome: HpWelcomeData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageWelcome.json');
const homePageWelcomeBackground: HpWelcomeBackgroundData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageWelcomeBackground.json');

const FlatListAnimated = Animated.createAnimatedComponent(FlatList);
type PageContainerPropsType = {
  scrollVeticalIndex: number;
  onSetIndex: () => void;
};
const PageContainer: React.FC<PageContainerPropsType> = (props) => {
  const { theme } = useTheme();
  // const { t, i18n } = useTranslation(['PageContainer']);
  const [isPersonal, setIsPersonal] = useState(true);
  const { scrollVeticalIndex, onSetIndex } = props;
  const insets = useSafeAreaInsets();
  const styles = useStyles();
  // const currentIndex = useSharedValue(0);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [currentIndexVertical, setCurrentIndexVertical] = useState(0);
  const [listVideoData, setListVideoData] = useState([]);
  const [isMuteVideo, setIsMuteVideo] = useState(false);
  const token = Storage.retrieve(STORAGE_KEY.USER_AUTH);
  const [isLogin, setIsLogin] = useState(!isEmpty(token));

  const [loading, setLoading] = useState(false);
  console.log('token?.idToken', token?.idToken);
  const flashListRef = useRef(null);
  useEffect(() => {
    if (
      scrollVeticalIndex != null &&
      scrollVeticalIndex !== currentIndexVertical
    ) {
      setCurrentIndexVertical(scrollVeticalIndex);
      flashListRef?.current?.scrollToIndex({
        index: scrollVeticalIndex,
      });
      onSetIndex?.();
    }
  }, [scrollVeticalIndex, flashListRef]);
  useEffect(() => {
    setLoading(false);
    setIsLogin(!isEmpty(token));
  }, [token]);
  const height = theme.Size.DEVICE_HEIGHT - 76 - insets.bottom;
  let dataWelcomePersonal = useMemo(
    () =>
      homePageWelcome?.data?.find(
        (d) => d?.hp_customer_type?.customer_type_name === 'personal',
      ),
    [],
  );
  let dataWelcomeBusiness = useMemo(
    () =>
      homePageWelcome?.data?.find(
        (d) => d?.hp_customer_type?.customer_type_name === 'business',
      ),
    [],
  );
  let dataWelcomeBg = isPersonal
    ? [
        ...homePageWelcomeBackground?.data?.filter(
          (d) => d?.hp_customer_type?.customer_type_name === 'personal',
        ),
      ]
    : [
        ...homePageWelcomeBackground?.data?.filter(
          (d) => d?.hp_customer_type?.customer_type_name === 'business',
        ),
      ];
  let dataBusiness = useMemo(
    () =>
      homePageProductSection.data.filter(
        (d) => d.hp_customer_type?.customer_type_name === 'business',
      ),
    [],
  );
  let dataPersonal = useMemo(
    () =>
      homePageProductSection.data.filter(
        (d) => d.hp_customer_type?.customer_type_name === 'personal',
      ),
    [],
  );

  useEffect(() => {
    let hp_welcome_backgrounds_data: string[] = [];
    for (
      let i = 0;
      i < dataWelcomePersonal?.hp_welcome_backgrounds?.length;
      i++
    ) {
      let element = dataWelcomePersonal?.hp_welcome_backgrounds[i];

      const find_hp_welcome_backgrounds_data = dataWelcomeBg?.filter(
        (e) => e.id == element?.id,
      );
      hp_welcome_backgrounds_data = [
        ...hp_welcome_backgrounds_data,
        ...find_hp_welcome_backgrounds_data,
      ];
    }
    dataWelcomePersonal.hp_welcome_backgrounds = [
      ...hp_welcome_backgrounds_data,
    ];
    const find_hp_menu_items = homePageMenu.data?.find(
      (menu) => menu.id === dataWelcomePersonal?.hp_home_menu.id,
    );
    dataWelcomePersonal.hp_home_menu = find_hp_menu_items;
  }, [dataWelcomePersonal]);

  useEffect(() => {
    let hp_welcome_backgrounds_data: string[] = [];
    for (
      let i = 0;
      i < dataWelcomeBusiness?.hp_welcome_backgrounds?.length;
      i++
    ) {
      let element = dataWelcomeBusiness?.hp_welcome_backgrounds[i];

      const find_hp_welcome_backgrounds_data = dataWelcomeBg?.filter(
        (e) => e.id == element?.id,
      );
      hp_welcome_backgrounds_data = [
        ...hp_welcome_backgrounds_data,
        ...find_hp_welcome_backgrounds_data,
      ];
    }
    dataWelcomeBusiness.hp_welcome_backgrounds = [
      ...hp_welcome_backgrounds_data,
    ];
    const find_hp_menu_items = homePageMenu.data?.find(
      (menu) => menu.id === dataWelcomeBusiness?.hp_home_menu.id,
    );
    dataWelcomeBusiness.hp_home_menu = find_hp_menu_items;
  }, [dataWelcomeBusiness]);

  useEffect(() => {
    for (let i = 0; i < dataPersonal?.length; i++) {
      let element = dataPersonal[i];
      let hp_product_section_backgrounds_data: string[] = [];
      let hp_product_section_card_data = {};
      for (let j = 0; j < element.hp_product_section_backgrounds?.length; j++) {
        const find_hp_product_section_backgrounds =
          homePageProductSectionBackground?.data?.filter(
            (e) => e.id == element?.hp_product_section_backgrounds?.[j]?.id,
          );
        hp_product_section_backgrounds_data = [
          ...hp_product_section_backgrounds_data,
          ...find_hp_product_section_backgrounds,
        ];
      }

      const find_hp_product_card = homePageProductSectionCard?.data?.find(
        (e) => e.id == element?.hp_product_card?.id,
      );
      hp_product_section_card_data = find_hp_product_card;

      element.hp_product_section_backgrounds_data = [
        ...hp_product_section_backgrounds_data,
      ];
      element.hp_product_section_card_data = hp_product_section_card_data;
      dataPersonal[i] = element;
    }
  }, [dataPersonal, dataPersonal?.length]);

  useEffect(() => {
    for (let i = 0; i < dataBusiness?.length; i++) {
      let element = dataBusiness[i];
      let hp_product_section_backgrounds_data: string[] = [];
      let hp_product_section_card_data: string[] = [];
      for (let j = 0; j < element.hp_product_section_backgrounds?.length; j++) {
        const find_hp_product_section_backgrounds =
          homePageProductSectionBackground?.data?.filter(
            (e) => e.id == element?.hp_product_section_backgrounds?.[j]?.id,
          );
        hp_product_section_backgrounds_data = [
          ...hp_product_section_backgrounds_data,
          ...find_hp_product_section_backgrounds,
        ];
      }

      const find_hp_product_card = homePageProductSectionCard?.data?.find(
        (e) => e.id == element?.hp_product_card?.id,
      );
      hp_product_section_card_data = find_hp_product_card;

      element.hp_product_section_backgrounds_data = [
        ...hp_product_section_backgrounds_data,
      ];
      element.hp_product_section_card_data = hp_product_section_card_data;
      dataBusiness[i] = element;
    }
  }, [dataBusiness, dataBusiness?.length]);
  const setIndexHorizontal = (i: number) => {
    setCurrentIndex(i);
  };
  const dataRender = useMemo(
    () =>
      isPersonal
        ? [dataWelcomePersonal, ...dataPersonal]
        : [dataWelcomeBusiness, ...dataBusiness],
    [
      isPersonal,
      dataBusiness,
      dataPersonal,
      dataWelcomeBusiness,
      dataWelcomePersonal,
    ],
  );

  useEffect(() => {
    const getListVideo = () => {
      let listVideoURL: string[] = [];
      for (let i = 0; i < dataRender?.length; i++) {
        let listVideoURLVertical: string[] = [];
        if (i == 0) {
          for (
            let j = 0;
            j < dataRender[i]?.hp_welcome_backgrounds?.length;
            j++
          ) {
            // listVideoURLVertical.push(
            //   dataRender[i].hp_welcome_backgrounds_data[j].media_items,
            // );
            listVideoURLVertical = [
              ...listVideoURLVertical,
              dataRender[i].hp_welcome_backgrounds[j].media_items,
            ];
          }
        } else {
          for (
            let j = 0;
            j < dataRender[i]?.hp_product_section_backgrounds_data?.length;
            j++
          ) {
            // listVideoURLVertical.push(
            //   dataRender[i].hp_product_section_backgrounds_data[j]?.media_item,
            // );
            listVideoURLVertical = [
              ...listVideoURLVertical,
              dataRender[i].hp_product_section_backgrounds_data[j]?.media_item,
            ];
          }
        }
        // listVideoURL.push(listVideoURLVertical);
        listVideoURL = [...listVideoURL, listVideoURLVertical];
      }
      setListVideoData(listVideoURL);
    };
    getListVideo();
  }, [
    isPersonal,
    dataBusiness,
    dataPersonal,
    dataWelcomeBusiness,
    dataWelcomePersonal,
    dataRender,
    dataRender?.length,
  ]);
  const renderBottomSocial = useMemo(() => {
    return <ListSocial />;
  }, []);

  const setMuted = (muted: boolean) => {
    setIsMuteVideo(muted);
  };
  console.log('dataRender', JSON.stringify(dataRender));
  const renderItems = ({ item, index }) => {
    console.log('renderItems5', currentIndex);
    return (
      <View style={[styles.pageScrollContainer, { height: height }]}>
        <PageScroll
          data={listVideoData?.[currentIndexVertical]}
          dataVideo={listVideoData?.[currentIndexVertical]}
          indexHorizontal={currentIndex}
          setIndexHorizontal={setIndexHorizontal}
        />
        {index === 0 ? (
          <PageWelcome
            totalPages={listVideoData?.[currentIndexVertical]?.length}
            indexHorizontal={currentIndex}
            isMuteVideo={isMuteVideo}
            setMuteVideo={setMuted}
            data={item}
            setIndexHorizontal={setIndexHorizontal}
          />
        ) : (
          <PageSections
            item={item}
            index={index}
            indexHorizontal={currentIndex}
            setIndexHorizontal={setIndexHorizontal}
            totalPages={listVideoData?.[currentIndexVertical]?.length}
          />
        )}
      </View>
    );
  };

  const onVideoEnd = () => {
    if (currentIndex < listVideoData?.[currentIndexVertical]?.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setCurrentIndex(0);
    }
  };

  const scrollHandler = (event) => {
    const totalHeight = event.nativeEvent.layoutMeasurement.height;
    const yPosition = event.nativeEvent.contentOffset.y;
    const newIndex = Math.round(yPosition / totalHeight);
    console.log('scrollHandlerVerical', newIndex);
    if (newIndex !== currentIndexVertical) {
      newIndex > 0
        ? setCurrentIndexVertical(newIndex)
        : setCurrentIndexVertical(0);
      setCurrentIndex(0);
    }
  };
  return (
    <View style={styles.container}>
      <View style={styles.videoContainer}>
        <VideoBackground
          muted={isMuteVideo}
          pause={false}
          repeat={listVideoData?.[currentIndexVertical]?.length < 2}
          onVideoEnd={onVideoEnd}
          source={listVideoData?.[currentIndexVertical]?.[currentIndex]}
        />
      </View>
      <FlatListAnimated
        // onIndexChange={function (index: number): void { }}
        data={dataRender}
        ref={flashListRef}
        style={styles.list}
        onScroll={scrollHandler}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.contentList}
        snapToInterval={height}
        snapToAlignment={'start'}
        decelerationRate={'fast'}
        ListFooterComponent={renderBottomSocial}
        renderItem={renderItems}
        extraData={[
          currentIndexVertical,
          currentIndex,
          listVideoData,
          dataRender,
        ]}
      />
      <HeaderBar
        onChangeUserType={(b) => {
          setCurrentIndex(0);
          setCurrentIndexVertical(0);
          flashListRef?.current?.scrollToIndex({
            index: 0,
          });
          setIsPersonal(b);
        }}
        setLoading={setLoading}
      />
      <Hotline />
      {loading ? <LoadingBlockerView /> : null}
    </View>
  );
};
const useStyles = createStyles((theme) => ({
  container: {
    flex: 1,
    backgroundColor: theme.Colors.Background.Neutral100,
  },
  contentContainer: {
    flex: 1,
    paddingHorizontal: theme.Size.Horizontal.Medium,
    backgroundColor: 'transparent',
  },
  videoContent: {
    width: theme.Size.DEVICE_WIDTH,
    height: '100%',
    position: 'absolute',
  },
  pageScrollContainer: {
    backgroundColor: 'transparent',
    flex: 1,
  },
  videoContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  },
  list: {
    flex: 1,
  },
  contentList: {},
}));
export { PageContainer };
