import { Container } from 'inversify';
import { TYPES } from './types/types';
import { IHomepageRepository } from '@src/domain/interfaces/homepage';
import { HomepageRepository } from '@src/infrastructure/persistent/homepage/homepage.repository';
import { GetLocationHandler } from '@src/application/location/queries/get_location/get_location_handler';
import { ILocationRepository } from '@src/domain/interfaces/location';
import { LocationRepository } from '@src/infrastructure/persistent/location/location.repository';
import { GetHomepageHandler } from '@src/application/homepage/queries/get_homepage/get_homepage_handler';

const container = new Container();
container
  .bind<IHomepageRepository>(TYPES.IHomepageRepository)
  .to(HomepageRepository);

container
  .bind<GetHomepageHandler>(TYPES.GetHomepageHandler)
  .to(GetHomepageHandler);

container
  .bind<GetLocationHandler>(TYPES.GetLocationHandler)
  .to(GetLocationHandler);

container
  .bind<ILocationRepository>(TYPES.ILocationRepository)
  .to(LocationRepository);

export { container };
