import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback, useEffect } from 'react';
import { STORAGE_KEY, Storage, useTranslation } from '@core/service';
import { Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { HomePageMenuItem, HomePageMenuItemType } from './HomePageMenuItem';
import { CTAButtonWelcome } from '../CTAButtonWelcome';
import { CTAButtonWelcomeLogin } from '../CTAButtonWelcome/CTAButtonWelcomeLogin';
import { isEmpty } from 'lodash';
import { HpWelcome, MenuItem } from '@src/domain/entities/homepage';

const homePageData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepagemenu.json');
const homePageWelcomeBackground = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageWelcomeBackground.json');

type HomePageMenuPropsType = {
  data: HpWelcome;
};
const HomePageMenu: React.FC<HomePageMenuPropsType> = (props) => {
  const { theme } = useTheme();
  const { data } = props;
  const { t, i18n } = useTranslation(['HomePageMenu']);
  const styles = useStyles();
  const [isPersional, setIsPersional] = useState(true);

  const token = Storage.retrieve(STORAGE_KEY.USER_AUTH);
  const [isLogin, setIsLogin] = useState(!isEmpty(token));
  useEffect(() => {
    setIsLogin(!isEmpty(token));
  }, [token]);
  const insets = useSafeAreaInsets();
  const [videoIndex, setVideoIndex] = useState(0);
  const dataWelcome = isPersional ? homePageWelcomeBackground?.data?.filter((d) => d?.hp_customer_type?.customer_type_name === 'personal') : homePageWelcomeBackground?.data?.filter((d) => d?.hp_customer_type?.customer_type_name === 'business');
  return (
    <View style={[styles.container]}>
      {isLogin ? <CTAButtonWelcomeLogin data={data?.hp_welcome_backgrounds?.[videoIndex]?.cta_button} /> :
        <CTAButtonWelcome data={data?.hp_welcome_backgrounds?.[videoIndex]?.cta_button} />}
      <ScrollView horizontal contentContainerStyle={styles.contentContainerStyle}>
        {data?.hp_home_menu?.menu_items?.map((item: MenuItem, index: number) => {
          return (
            <HomePageMenuItem item={item} index={index} key={item.id} />
          );
        })}
      </ScrollView>

    </View>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    paddingHorizontal: theme.Size.Horizontal.Medium,
    gap: theme.Size.Vertical.Base,
  },
  contentContainerStyle: {
    justifyContent: 'space-between',
    gap: 12,
  },
}));
export { HomePageMenu };
