import React, { FC, memo, useCallback, useEffect, useState } from 'react';
import { Text, Image, TouchableOpacity, View } from 'react-native';

import { Switch, createStyles, useTheme } from '@core/ui';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';
import { MenuItemType, areEqualMemo, getIconDefault } from '../../constants';
import { DrawerActions, useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { MainStackParamList } from '@src/presentation/navigation/MainNavigator';
import { useDispatch } from 'react-redux';
import { DrawerContentComponentProps } from '@react-navigation/drawer';
import { handlePushMiniApp } from '@src/presentation/navigation/Utils';

interface MenuItemPropsProps {
  expandedSections: string;
  sectionTitle: string;
  item: MenuItemType;
  index: number;
  drawerProps: DrawerContentComponentProps;
}

const MenuItem: FC<MenuItemPropsProps> = (props) => {
  const { expandedSections, sectionTitle, item, index, drawerProps } = props;
  const { theme } = useTheme();
  const { navigation } = drawerProps;

  const styles = useStyles();

  const [isToggleEnable, setToggleEnable] = useState<boolean>(false);
  const animationHeight = useSharedValue(0);

  const animatedStyle = useAnimatedStyle(() => ({
    height: animationHeight.value,
    alignItems: 'center',
    overflow: 'hidden',
  }));

  useEffect(() => {
    animationHeight.value = withTiming(
      expandedSections === sectionTitle ? theme.Scaling.ms(40) : 0,
      {
        duration: 300,
      },
    );
  }, [
    animationHeight,
    expandedSections,
    sectionTitle,
    theme.Scaling,
    theme.Size.Vertical.Large,
  ]);

  const handleNavigation = useCallback(() => {
    if (item.url) {
      navigation.navigate('WebViewScreen', {
        url: item.url,
        title: item.label,
      });
      return;
    }

    switch (item.label) {
      case 'Tạo mã HDBank OTP':
        handlePushMiniApp('open_app', {
          appName: 'SoftOtp',
        });
        return;
      case 'Sản phẩm vay':
        navigation.navigate('TabNavigation', {
          screen: 'HomePage',
          params: { scrollVeticalIndex: 3 },
          merge: true,
        });
        return;
      case 'Thẻ':
        navigation.navigate('TabNavigation', {
          screen: 'HomePage',
          params: { scrollVeticalIndex: 1 },
          merge: true,
        });

        return;
      case 'Sản phẩm tiền gửi':
        navigation.navigate('TabNavigation', {
          screen: 'HomePage',
          params: { scrollVeticalIndex: 2 },
          merge: true,
        });
        return;
      case 'Ưu đãi':
        navigation.navigate('TabNavigation', {
          screen: 'HomePage',
          params: { scrollVeticalIndex: 3 },
        });
        return;
      case 'Game':
        navigation.navigate('TabNavigation', {
          screen: 'HomePage',
          params: { scrollVeticalIndex: 4 },
        });
        return;
      default:
        return;
    }
  }, [navigation, item]);

  return (
    <TouchableOpacity onPress={handleNavigation}>
      <Animated.View
        key={index}
        style={[
          animatedStyle,
          styles.container,
          index === 0 && styles.firstItemStyle,
        ]}
      >
        {item?.icon ? (
          <Image source={{ uri: item?.icon ?? '' }} style={styles.imageStyle} />
        ) : (
          getIconDefault(item?.label)
        )}
        <View style={styles.wrapperRight}>
          <Text
            style={[
              styles.titleStyle,
              theme.Typography.TextBody.Regular,
              item?.label_color && { color: item?.label_color },
              item?.label_font && { fontFamily: item?.label_font },
            ]}
          >
            {item?.label ?? ''}
          </Text>
          {item?.label === 'Xác thực với Face ID' && (
            <View style={styles.wrapperSwitch}>
              <Switch
                onToggle={() => setToggleEnable(!isToggleEnable)}
                isOn={isToggleEnable}
                size="small"
              />
            </View>
          )}
        </View>
      </Animated.View>
    </TouchableOpacity>
  );
};

export default memo(MenuItem, areEqualMemo);

const useStyles = createStyles((theme) => ({
  container: {
    marginHorizontal: theme.Size.Horizontal.Large,
    flexDirection: 'row',
  },
  imageStyle: {
    width: theme.Scaling.ms(24),
    height: theme.Scaling.ms(24),
  },
  titleStyle: {
    marginLeft: theme.Size.ModerateHorizontal.Base,
  },
  wrapperRight: {
    flex: 1,
    justifyContent: 'space-between',
    flexDirection: 'row',
    alignItems: 'center',
  },
  wrapperSwitch: {
    alignSelf: 'flex-end',
  },
  firstItemStyle: {
    marginTop: -theme.Size.Vertical.Large,
  },
}));
