import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
  BottomSheetManager,
  BottomSheet,
  BottomSheetMethod,
} from '@core/ui';
import React, { useState, useCallback, useRef, useEffect } from 'react';
import {
  STORAGE_KEY,
  OpenAppPayload,
  useChangeLanguage,
  useTranslation,
  Storage,
} from '@core/service';
import { Image, ScrollView, TouchableOpacity, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import {
  icDrawer,
  icFlagEN,
  icFlagVN,
  icNoti,
  icSearch,
  icVN,
  logoHDBank,
} from '@src/assets/images';
import { DrawerActions, useNavigation } from '@react-navigation/native';
import { RadioButton } from '../Choice';
import { isEmpty } from 'lodash';
import { PaletteLight } from '@src/theme/palette';
import { handlePushMiniApp } from '@src/presentation/navigation/Utils';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { MainStackParamList } from '@src/presentation/navigation/MainNavigator';

type dataMenuItemType = {
  id: number;
  name: string;
  icon: null | string;
  type: 'personal' | 'business' | 'login';
};
type HeaderBarPropsType = {
  onChangeUserType: () => void;
  setLoading: () => void;
};

const HeaderBar: React.FC<HeaderBarPropsType> = (props) => {
  const { onChangeUserType, setLoading } = props;

  const { theme } = useTheme();
  const navigation =
    useNavigation<NativeStackNavigationProp<MainStackParamList>>();

  const { t, i18n } = useTranslation(['headerBar']);

  const changeLanguage = useChangeLanguage();
  const styles = useStyles();

  const [selectedMenuTop, setSellectedMenuTop] = useState(0);

  const modalRef = useRef<BottomSheetMethod>(null);
  const scrollViewRef = useRef<ScrollView>(null);

  const insets = useSafeAreaInsets();
  const token = Storage.retrieve(STORAGE_KEY.USER_AUTH);
  const [isLogin, setIsLogin] = useState(!isEmpty(token));
  useEffect(() => {
    setIsLogin(!isEmpty(token));
  }, [token]);
  const dataMenu: dataMenuItemType[] = [
    {
      id: 79,
      type: 'personal',
      name: t('personal'),
      icon: null,
    },
    {
      id: 80,
      type: 'business',
      name: t('business'),
      icon: null,
    },
  ];
  const onPressMenuTop = useCallback(
    async (item: dataMenuItemType, index: number) => {
      onChangeUserType?.(index === 0);
      setSellectedMenuTop(index);
      scrollViewRef.current?.scrollTo({
        x: index * 100, // Giá trị x thay đổi tùy theo kích thước item
        animated: true,
      });
    },
    [onChangeUserType],
  );

  const switchLanguage = useCallback(
    (lg: 'en' | 'vi') => {
      changeLanguage(lg);
      modalRef?.current?.close();
    },
    [changeLanguage],
  );

  const showBotomSheet = useCallback(() => {
    BottomSheetManager.show({
      render: (bottomSheetLg) => (
        <BottomSheet
          id={bottomSheetLg}
          title={t('changeLgTitle')}
          ref={modalRef}
        >
          <View>
            <RadioButton
              position="right"
              isDotIcon
              checked={i18n.language === 'vi'}
              onPress={() => {
                switchLanguage('vi');
              }}
              componentLeft={
                <View style={styles.wrapperLag}>
                  <Image style={[styles.iconChangeLg]} source={icFlagVN} />
                  <Text style={[styles.textRadioStyle]}>{t('vietnamese')}</Text>
                </View>
              }
              textStyle={styles.textRadioStyle}
              containerStyle={styles.containerRadioStyle}
            />
            <View style={styles.lineStyle} />
            <RadioButton
              position="right"
              isDotIcon
              checked={i18n.language === 'en'}
              componentLeft={
                <View style={styles.wrapperLag}>
                  <Image style={[styles.iconChangeLg]} source={icFlagEN} />
                  <Text style={[styles.textRadioStyle]}>{t('english')}</Text>
                </View>
              }
              onPress={() => {
                switchLanguage('en');
              }}
              containerStyle={styles.containerRadioStyle}
            />
          </View>
        </BottomSheet>
      ),
    });
  }, [
    i18n.language,
    styles.containerRadioStyle,
    styles.iconChangeLg,
    styles.lineStyle,
    styles.textRadioStyle,
    styles.wrapperLag,
    switchLanguage,
    t,
  ]);

  const handleToggleDrawer = () => {
    navigation.navigate('Drawer', { selectedMenuTop: selectedMenuTop });
    navigation.dispatch(DrawerActions.toggleDrawer());
  };
  const onLogin = () => {
    setLoading(true);
    handlePushMiniApp('open_app', {
      appName: 'AuthApp',
      screen: 'LoginUsername',
    });
  };
  return (
    <View style={[styles.container, { top: insets.top }]}>
      <TouchableOpacity onPress={handleToggleDrawer}>
        <Image style={styles.iconDrawer} source={icDrawer} />
      </TouchableOpacity>
      <Image style={styles.logoHDB} source={logoHDBank} />
      <ScrollView
        horizontal
        ref={scrollViewRef}
        showsHorizontalScrollIndicator={false}
        style={styles.scrollViewContainer}
        contentContainerStyle={styles.scrollViewContentContainer}
      >
        {dataMenu.map((item: dataMenuItemType, index: number) => (
          <View key={index}>
            <BaseButton
              disabled={selectedMenuTop === index}
              onPress={() => onPressMenuTop(item, index)}
            >
              <Text
                style={[
                  styles.textButton,
                  selectedMenuTop === index && {
                    color: theme.Colors.Text.Error,
                  },
                ]}
              >
                {item.name}
              </Text>
            </BaseButton>
          </View>
        ))}
      </ScrollView>
      {isLogin ? (
        <>
          <Image style={styles.iconDrawer} source={icSearch} />
          <Image style={styles.iconDrawer} source={icNoti} />
        </>
      ) : (
        <>
          <BaseButton style={styles.buttonLoginStyle} onPress={onLogin}>
            <Text style={[styles.textButton]}>{t('login')}</Text>
          </BaseButton>
          <BaseButton style={styles.buttonChangeLg} onPress={showBotomSheet}>
            <Image style={[styles.iconChangeLg]} source={icVN} />
          </BaseButton>
        </>
      )}
    </View>
  );
};
const useStyles = createStyles((theme) => ({
  container: {
    flexDirection: 'row',
    gap: 4,
    justifyContent: 'center',
    alignItems: 'center',
    height: 44,
    paddingHorizontal: 4,
    width: '100%',
    backgroundColor: 'transparent',
    position: 'absolute',
    left: 0,
    right: 0,
  },
  scrollViewContainer: {
    flex: 3,
  },
  buttonLoginStyle: {
    flex: 1,
    backgroundColor: theme.Colors.Background.Neutral200,
    padding: theme.Scaling.ms(8),
    borderRadius: theme.Scaling.ms(1000),
    justifyContent: 'center',
    alignItems: 'center',
  },
  scrollViewContentContainer: {
    gap: 8,
    alignItems: 'center',
  },
  iconDrawer: {
    width: theme.Size.Horizontal.xxxLarge,
    height: theme.Size.Vertical.xxxLarge,
  },
  textButton: {
    ...theme.Typography.TextCaption100.Bold,
  },
  buttonChangeLg: {
    width: theme.Size.Horizontal.xxxLarge,
    height: theme.Size.Vertical.xxxLarge,
    justifyContent: 'center',
    alignItems: 'center',
    flexDirection: 'row',
  },
  iconChangeLg: {
    width: theme.Size.Horizontal.xxxLarge,
    height: theme.Size.Vertical.xxxLarge,
  },
  logoHDB: {
    height: 28,
    width: theme.Size.Horizontal.Gigantic,
  },
  textRadioStyle: {
    ...theme.Typography.TextBody.Regular,
    marginLeft: theme.Size.ModerateHorizontal.Base,
  },
  containerRadioStyle: {
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  lineStyle: {
    height: 1,
    marginVertical: theme.Size.ModerateVertical.Regular,
    backgroundColor: PaletteLight.neutral['300'],
  },
  wrapperLag: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
  },
}));
export { HeaderBar };
