import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import { BannerWelcome } from '@src/presentation/homepage/components';
import { CTAButton } from '@src/presentation/homepage/components/CTAButton';
import { HomePageCard } from '@src/presentation/homepage/components/HomePageCard/HomePageCard';
import { HomePageMenu } from '@src/presentation/homepage/components/HomePageMenu';
import { Hotline } from '@src/presentation/homepage/components/Hotline';
import { LeftMenu } from '@src/presentation/homepage/components/LeftMenu';
import { Pagination } from '@src/presentation/homepage/components/Pagination';
import { SectionsTitle } from '@src/presentation/homepage/components/SectionsTitle';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
// import { useTranslation } from '@core/service';
import { View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

type PageSectionsPropsType = {
  item: object;
  index: number;
  indexHorizontal: number;
  setIndexHorizontal: (page: number) => void;
  totalPages: number;
}
const PageSections: React.FC<PageSectionsPropsType> = (props) => {
  const { theme } = useTheme();
  // const { t, i18n } = useTranslation(['PageSections']);
  const { item, index, indexHorizontal, setIndexHorizontal, totalPages } = props;
  const insets = useSafeAreaInsets();
  const styles = useStyles();
  const [isLogin, setIsLogin] = useState(false);
  const [isPersonal, setIsPersonal] = useState(true);
  const [currentPage, setCurrentPage] = useState(indexHorizontal);
  useEffect(() => {
    if (currentPage !== indexHorizontal) {
      setCurrentPage(indexHorizontal);
    }
  }, [indexHorizontal]);
  const handlePagination = (page) => {
    setCurrentPage(page);
    setIndexHorizontal(page);
  };

  return (
    <View style={[styles.page, { bottom: theme.Size.ms(56) }]}>
      <SectionsTitle item={item} />

      <View  >
        <Pagination
          currentPage={currentPage}
          setCurrentPage={handlePagination}
          totalPages={totalPages}
        />
        <CTAButton data={item?.hp_product_section_backgrounds_data?.[0]?.cta_button} description={item?.hp_product_section_backgrounds_data?.[0]?.description} />
      </View>
      <HomePageCard data={item?.hp_product_section_card_data} />
    </View>
  );
};
const useStyles = createStyles((theme) => ({

  page: {
    position: 'absolute',
    gap: theme.Size.Vertical.Medium,
    justifyContent: 'flex-end',
    left: 0,
    right: 0,
    top: 0,
    backgroundColor: 'transparent',
  },
}));
export { PageSections };
