import React from 'react';
import {
  CardIcon,
  DepositProductIcon,
  ForeignCurrencyIcon,
  GameIcon,
  InsuranceIcon,
  InvestIcon,
  LoanProductIcon,
  PromotionIcon,
  ServiceProductIcon,
  RemittanceServiceIcon,
  ForeignCurrencyRenewalIcon,
  CommerceFinancingIcon,
  CashFlowManagementIcon,
  AgentBankingIcon,
  CreditIcon,
  AddRoundIcon,
  ChangePinIcon,
  ConfirmFaceIDIcon,
} from '@src/assets';
import { isEqual } from 'lodash';

export const getIconDefault = (label: string) => {
  switch (label) {
    case 'Sản phẩm vay':
      return <LoanProductIcon />;
    case 'Thẻ':
      return <CardIcon />;
    case 'Dịch vụ kiều hối':
      return <RemittanceServiceIcon />;
    case 'Sản phẩm dịch vụ':
      return <ServiceProductIcon />;
    case 'Bảo hiểm':
      return <InsuranceIcon />;
    case 'Đầu tư':
      return <InvestIcon />;
    case 'Ngoại tệ':
      return <ForeignCurrencyIcon />;
    case 'Sản phẩm tiền gửi':
      return <DepositProductIcon />;
    case 'Ưu đãi':
      return <PromotionIcon />;
    case 'Game':
      return <GameIcon />;
    case 'Ngoại tệ & Phái sinh':
      return <ForeignCurrencyRenewalIcon />;
    case 'Ngoại tệ & Phái sinh':
      return <ForeignCurrencyRenewalIcon />;
    case 'Tài trợ thương mại':
      return <CommerceFinancingIcon />;
    case 'Quản lý dòng tiền':
      return <CashFlowManagementIcon />;
    case 'Ngân hàng đại lý':
      return <AgentBankingIcon />;
    case 'Tín dụng':
      return <CreditIcon />;
    case 'Tạo mã HDBank OTP':
      return <AddRoundIcon />;
    case 'Đổi mã PIN HDBank OTP':
      return <ChangePinIcon />;
    case 'Xác thực với Face ID':
      return <ConfirmFaceIDIcon />;
    default:
      return <></>;
  }
};

export const areEqualMemo = (prevProps: any, nextProps: any) => {
  return isEqual(prevProps, nextProps);
};
