import { Image, View } from 'react-native';
import React from 'react';
import { BottomTabBarProps } from '@react-navigation/bottom-tabs';
import { BottomBarItem } from './BottomBarItem';
import { OpenAppPayload, useTranslation } from '@core/service';

import { createStyles } from '@core/ui';
import {
  icBottomAccount,
  icBottomApprove,
  icBottomCard,
  icBottomCrown,
  icBottomDeposit,
  icBottomHDB,
  icBottomQRcode,
  icBottomSave,
} from '@src/assets/images';
import { MainScreenStackParams } from '@src/navigation/TabNavigation';
import { ParamListRoute } from '@react-navigation/native';
import { handlePushMiniApp } from '@src/presentation/navigation/Utils';

type BottomItemType = {
  label?: string;
  icon: React.ReactNode;
  onPress: () => void;
  active?: boolean;
  floating?: boolean;
};

type ListBottomBarDataType = {
  persional: BottomItemType[];
  business: BottomItemType[];
};

const BottomBar = ({ state, navigation, insets }: BottomTabBarProps) => {
  const handleBottomBarItemPress = (
    routeName: keyof MainScreenStackParams,
    params?: never,
  ) => {
    navigation.navigate(routeName as string, params);
  };
  const { t } = useTranslation(['bottomBar']);
  const styles = useStyles();
  const isBusiness = false;
  const listBottomBarData: ListBottomBarDataType = {
    persional: [
      {
        label: t('home'),
        icon: <Image source={icBottomHDB} style={styles.iconSize} />,
        onPress: () =>
          handleBottomBarItemPress('HomePage', { scrollVeticalIndex: 0 }),
      },
      {
        label: t('skyJoy'),
        icon: <Image source={icBottomCrown} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
      {
        icon: <Image source={icBottomQRcode} style={styles.iconFloatingSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
        floating: true,
      },
      {
        label: t('card'),
        icon: <Image source={icBottomCard} style={styles.iconSize} />,
        onPress: () =>
          handlePushMiniApp('open_app', { appName: 'CardManagement' }),
      },
      {
        label: t('save'),
        icon: <Image source={icBottomSave} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
    ],
    business: [
      {
        label: t('home'),
        icon: <Image source={icBottomHDB} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
      {
        label: t('account'),
        icon: <Image source={icBottomAccount} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
      {
        icon: <Image source={icBottomQRcode} style={styles.iconFloatingSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
        floating: true,
      },
      {
        label: t('card'),
        icon: <Image source={icBottomApprove} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
      {
        label: t('save'),
        icon: <Image source={icBottomDeposit} style={styles.iconSize} />,
        onPress: () => handleBottomBarItemPress('HomePage'),
      },
    ],
  };
  const listBottomBar = isBusiness
    ? listBottomBarData.business
    : listBottomBarData.persional;
  return (
    <View
      style={{
        ...styles.container,
        paddingBottom: insets.bottom + 12,
        height: 76 + insets.bottom,
      }}
    >
      {listBottomBar?.map((item: BottomItemType) => {
        return (
          <BottomBarItem
            key={item.label}
            label={item.label}
            icon={item.icon}
            onPress={item.onPress}
            isFloating={item.floating}
          />
        );
      })}
    </View>
  );
};

export { BottomBar };

const useStyles = createStyles((theme) => ({
  container: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    backgroundColor: theme.Colors.Background.White,
    paddingVertical: 10,
  },
  iconSize: {
    width: theme.Size.Horizontal.xxxLarge,
    height: theme.Size.Vertical.xxxLarge,
  },
  iconFloatingSize: {
    width: theme.Size.Horizontal.ExtraLarge,
    height: theme.Size.Vertical.ExtraLarge,
    // marginTop: -theme.Size.Vertical.Medium,
  },
}));
