import { useNavigation } from '@react-navigation/native';
import React, { useEffect, useState } from 'react';
import { useTranslation } from '@core/service';
import { createStyles, SafeAreaContainer, Spacer } from '@core/ui';
import { View } from 'react-native';
import { PageContainer } from '../HomepageInfo';

const HomePageScreen: React.FC = ({ route }) => {
  const navigation = useNavigation();
  const { t } = useTranslation(['homePageScreen']);
  const scrollVeticalIndex = route?.params?.scrollVeticalIndex;

  const [indexVertical, setIndexVertical] = useState(
    scrollVeticalIndex || null,
  );

  const styles = useStyles();

  useEffect(() => {
    console.log('scrollVeticalIndex', scrollVeticalIndex);
    if (scrollVeticalIndex != null) {
      setIndexVertical(scrollVeticalIndex);
    }
  }, [scrollVeticalIndex]);
  const onCloseApp = () => {
    if (navigation.canGoBack()) {
      navigation.goBack();
    }
  };
  const onSetIndex = () => {
    setIndexVertical(null);
    navigation.setParams({ scrollVeticalIndex: null });
  };
  return (
    <View style={[styles.container, {}]}>
      <PageContainer
        scrollVeticalIndex={indexVertical}
        onSetIndex={onSetIndex}
      />
    </View>
  );
};

const useStyles = createStyles((theme) => ({
  container: {
    flex: 1,
    backgroundColor: 'transparent',
  },
}));

export { HomePageScreen };
